css:
.sl-footer-academic {
    padding-top: 4.5rem;
    font-family: var(--smartlearn-body-font, inherit);
}
.sl-footer-academic .sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-footer-academic .sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-footer-academic .sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-footer-academic.sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-footer-academic.sl-border,
.sl-footer-academic .row.sl-border { border-color: var(--smartlearn-card-border) !important; }

.sl-footer-academic .sl-footer-link {
    transition: color 0.2s ease;
}
.sl-footer-academic .sl-footer-link:hover,
.sl-footer-academic .sl-footer-link:focus-visible {
    color: var(--smartlearn-primary) !important;
    text-decoration: underline !important;
}
.sl-footer-academic .sl-social-icon {
    min-width: 36px;
    min-height: 36px;
    transition: color 0.2s ease, transform 0.2s ease;
}
.sl-footer-academic .sl-social-icon:hover,
.sl-footer-academic .sl-social-icon:focus-visible {
    color: var(--smartlearn-primary) !important;
    transform: translateY(-2px);
}
.sl-footer-academic a:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
    .sl-footer-academic .sl-footer-link,
    .sl-footer-academic .sl-social-icon { transition: none; }
    .sl-footer-academic .sl-social-icon:hover,
    .sl-footer-academic .sl-social-icon:focus-visible { transform: none; }
}
